package org.humanjourney.core.mapfeature;
import java.util.*;
import com.google.gson.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.humanjourney.core.mapfeature.GeometryV2Test.*;
import org.humanjourney.core.mapfeature.client.*;
import org.humanjourney.core.geography.*;
import org.humanjourney.core.water.WaterGeography.Point;
class GeometryCapacityTest {
 static FeatureGeometry manyHoles(){var holes=new ArrayList<FeatureGeometry.Ring>();for(int i=0;i<511;i++)holes.add(circle(32,i%23*30,i/23*30,5));return FeatureGeometry.polygon(new FeatureGeometry.Part(circle(32,0,0,5000),holes));}
 static FeatureGeometry manyParts(){var parts=new ArrayList<FeatureGeometry.Part>();for(int i=0;i<512;i++)parts.add(new FeatureGeometry.Part(circle(32,i*100,0,10),List.of()));return FeatureGeometry.multipolygon(parts);}
 static JsonArray points(List<Point> points){var out=new JsonArray();for(var p:points){var a=new JsonArray();a.add(p.x());a.add(p.z());out.add(a);}return out;}
 static JsonObject part(FeatureGeometry.Part part){var out=new JsonObject();out.add("outer",points(part.outer().points()));var holes=new JsonArray();part.holes().forEach(h->holes.add(points(h.points())));out.add("holes",holes);return out;}
 static String json(String id,FeatureGeometry geometry){var root=JsonParser.parseString(FeatureModelTest.polygon(id,1)).getAsJsonObject();root.addProperty("schema_version",2);var g=new JsonObject();g.addProperty("type",geometry.kind().name().toLowerCase(Locale.ROOT));if(geometry.kind()==FeatureGeometry.Kind.POLYLINE)g.add("points",points(geometry.points()));else if(geometry.kind()==FeatureGeometry.Kind.POLYGON){var p=part(geometry.parts().getFirst());for(String k:p.keySet())g.add(k,p.get(k));}else{var parts=new JsonArray();geometry.parts().forEach(p->parts.add(part(p)));g.add("polygons",parts);}root.add("geometry",g);return root.toString();}
 @AfterEach void reset(){FeatureCatalog.reset();}
 @Test void maximumManyHolePolygonLoadsAndExcludesAll511Islands(){var g=manyHoles();assertEquals(512,g.ringCount());assertEquals(16384,g.vertexCount());var parsed=feature(json("max_holes",g)).view().geometry();assertEquals(g,parsed);for(int i=0;i<511;i++)assertFalse(parsed.contains(i%23*30,i/23*30));assertTrue(parsed.contains(-1000,0));}
 @Test void maximumMultipartLoadsAndIndexesEachComponentSeparately(){var g=manyParts();var parsed=feature(json("max_parts",g)).view();assertEquals(512,parsed.geometry().ringCount());assertEquals(16384,parsed.geometry().vertexCount());var index=new FeatureIndex(List.of(parsed));assertEquals(511,index.hover(FeatureModelTest.DIM,51100,0,2).partIndex());assertEquals(1,index.hover(FeatureModelTest.DIM,0,0,2).candidates());assertTrue(index.queryParts(FeatureModelTest.DIM,FeatureIndex.around(50,0,2)).isEmpty());}
 @Test void viewportCulls511DistantPartsAndRetainsSelectedPath(){var f=view("max_parts",manyParts());var index=new FeatureIndex(List.of(f));var entries=FeaturePresentation.persistentParts(index,f.dimension(),FeatureIndex.around(0,0,20),FeatureMode.ALL);assertEquals(1,entries.size());assertEquals(0,entries.getFirst().partIndex());assertEquals(32,FeaturePresentation.paths(f,0).getFirst().points().size());}
 @Test void maximumOuterAndPolylineHave16384PointsAndLegacyStillRejects513(){assertEquals(16384,FeatureGeometry.polygon(new FeatureGeometry.Part(circle(16384,0,0,5000),List.of())).vertexCount());var points=new ArrayList<Point>();for(int i=0;i<16384;i++)points.add(new Point(i,i%2));assertEquals(16384,feature(json("line",FeatureGeometry.polyline(points))).view().geometry().vertexCount());assertThrows(RuntimeException.class,()->new FeatureGeometry(FeatureGeometry.Kind.POLYLINE,points.subList(0,513),null));points.add(new Point(16384,0));assertThrows(RuntimeException.class,()->FeatureGeometry.polyline(points));}
 @Test void parserRejects513PartsAnd513RingsBeforeBuildingAllGeometry(){var root=JsonParser.parseString(json("parts",manyParts())).getAsJsonObject();var parts=root.getAsJsonObject("geometry").getAsJsonArray("polygons");parts.add(parts.get(0));assertThrows(RuntimeException.class,()->MapFeature.parse(root));var holes=JsonParser.parseString(json("holes",manyHoles())).getAsJsonObject();var values=holes.getAsJsonObject("geometry").getAsJsonArray("holes");values.add(values.get(0));assertThrows(RuntimeException.class,()->MapFeature.parse(holes));}
 @Test void parserRejects16385AggregateVertices(){var root=JsonParser.parseString(json("parts",manyParts())).getAsJsonObject();root.getAsJsonObject("geometry").getAsJsonArray("polygons").get(0).getAsJsonObject().getAsJsonArray("outer").add(JsonParser.parseString("[12,12]"));assertThrows(RuntimeException.class,()->MapFeature.parse(root));}
 @Test void unchangedCatalogVertexQuotaAllows64MaximumFeaturesAndRejects65(){var g=manyParts();var views=new ArrayList<MapFeature.View>();for(int i=0;i<64;i++)views.add(view("f_"+i,g));assertDoesNotThrow(()->GeometryBudget.check(views));views.add(view("over",g));assertThrows(RuntimeException.class,()->GeometryBudget.check(views));assertEquals(1048576,FeatureGeometry.MAX_CATALOG_VERTICES);}
 @Test void unchangedCatalogRingQuotaAllows128MaximumRingFeaturesAndRejects129(){var p=new FeatureGeometry.Part(circle(3,0,0,10),List.of());var g=FeatureGeometry.multipolygon(Collections.nCopies(512,p));var views=new ArrayList<MapFeature.View>();for(int i=0;i<128;i++)views.add(view("f_"+i,g));assertDoesNotThrow(()->GeometryBudget.check(views));views.add(view("over",g));assertThrows(RuntimeException.class,()->GeometryBudget.check(views));assertEquals(65536,FeatureGeometry.MAX_CATALOG_RINGS);}
 @Test void actualReloadAcceptsBeyondOldResourceBoundAndKeepsLastValidAboveNewBound()throws Exception{var text=json("large",manyHoles());assertTrue(text.length()>524288);assertTrue(text.length()<2097152);new FeatureReloadTest().reload(text);assertEquals(1,FeatureCatalog.state().data().features().size());var old=FeatureCatalog.state();new FeatureReloadTest().reload(text+" ".repeat(2097153));assertSame(old.data(),FeatureCatalog.state().data());assertTrue(FeatureCatalog.state().error().contains("2 MiB"));}
 @Test void preparationAlsoRejectsOversizedResourceOutsideReloadReader(){assertThrows(RuntimeException.class,()->FeatureCatalog.prepare(List.of(new FeatureCatalog.Source("test:over","synthetic"," ".repeat(2097153)))));}
 @Test void strictIntersectionValidationRemainsAtLargeScale(){var ring=circle(16384,0,0,5000);var bad=new ArrayList<>(ring.points());Collections.swap(bad,2000,10000);assertThrows(RuntimeException.class,()->new FeatureGeometry.Ring(bad));var duplicate=new ArrayList<>(ring.points());duplicate.set(10000,duplicate.get(2000));assertThrows(RuntimeException.class,()->new FeatureGeometry.Ring(duplicate));}
 @Test void largeOuterStillRejectsTouchingCrossingAndNestedHoles(){var outer=circle(16000,0,0,5000);assertThrows(RuntimeException.class,()->new FeatureGeometry.Part(outer,List.of(circle(3,4999,0,2))));assertThrows(RuntimeException.class,()->new FeatureGeometry.Part(circle(4,0,0,5000),List.of(circle(32,0,0,20),circle(32,0,0,10))));}
 @Test void locationHudUsesLargeDiscoveredGeometryAndHolesWithoutStateChanges(){var f=view("sea",manyHoles());var s=new ClientFeatureState.Snapshot(null,Map.of("sea",f),new FeatureIndex(List.of(f)));var geo=new GeographyContext("macro","Macro","","");assertEquals("Label sea",FeatureLocationHud.resolve(true,geo,s,f.dimension(),-1000,0).primary());assertEquals(HudPresentation.of(true,geo),FeatureLocationHud.resolve(true,geo,s,f.dimension(),0,0));}
}
